// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  AppWindowIcon,
  CircleStopIcon,
  CopyIcon,
  DownloadIcon,
  MonitorIcon,
  PanelTopIcon,
  PauseIcon,
  Trash2Icon,
  VideoIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import {
  Bar,
  BrowserChrome,
  DemoStage,
  DockHeader,
  Toggle,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, COUNTDOWN, duration, ELAPSED, EXT, NAME, SOURCES } from './script'

const SOURCE_ICONS = [PanelTopIcon, AppWindowIcon, MonitorIcon]

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  const clock = { s: 0 }
  const paint = () => {
    const text = duration(Math.floor(clock.s))
    ;[...qa('timer'), q('pill-timer')].forEach((element) => {
      element.textContent = text
    })
  }

  step(0)
  move('mic', { at: 0.3 })
  click('mic')
  tl.to(q('mic-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('mic-knob'), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')

  step(1, '+=0.4')
  move('start')
  click('start')
  tl.to(q('view-setup'), { opacity: 0, duration: 0.25 }, '<')
  tl.fromTo(
    q('view-session'),
    { opacity: 0 },
    { opacity: 1, duration: 0.3, immediateRender: false },
    '<',
  )
  tl.fromTo(
    q('pill'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '<',
  )
  tl.set(q('countdown'), { opacity: 1 }, '<')
  for (let n = COUNTDOWN; n >= 1; n--) {
    tl.set(q('countdown-n'), { text: String(n) }, n === COUNTDOWN ? '<' : '>')
    tl.fromTo(
      q('countdown-n'),
      { scale: 1.4, opacity: 0 },
      { scale: 1, opacity: 1, duration: 0.35, ease: 'power3.out', immediateRender: false },
      '<',
    )
    tl.to({}, { duration: 0.45 })
  }
  tl.to(q('countdown'), { opacity: 0, duration: 0.2 })
  tl.set(qa('starting'), { opacity: 0 }, '<')
  tl.set(qa('timer'), { opacity: 1 }, '<')
  tl.set(q('pause'), { display: 'inline-flex' }, '<')
  const recording = tl.duration()
  move('page-toggle', { at: recording + 0.2 })
  click('page-toggle')
  tl.to(q('page-toggle-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('page-toggle-knob'), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')
  tl.fromTo(
    q('saved-banner'),
    { opacity: 0, y: -6 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '<0.2',
  )
  tl.to(clock, { s: ELAPSED, duration: 3.2, ease: 'none', onUpdate: paint }, recording)
  tl.fromTo(
    qa('rec-dot'),
    { opacity: 1 },
    {
      opacity: 0.25,
      duration: 0.5,
      repeat: 5,
      yoyo: true,
      ease: 'sine.inOut',
      immediateRender: false,
    },
    recording,
  )

  step(2, recording + 3.3)
  move('pill-stop')
  click('pill-stop')
  tl.set(q('pause'), { display: 'none' }, '<')
  tl.set(q('pill-timer'), { text: 'Saving' }, '<')
  tl.set(q('pill-dot'), { backgroundColor: '#f59e0b' }, '<')
  tl.to({}, { duration: 0.6 })
  tl.to(q('url-text'), {
    text: { value: 'chrome-extension://one-panel/recording.html', delimiter: '' },
    duration: 0.4,
    ease: 'none',
  })
  tl.set(q('pill'), { opacity: 0 }, '<')
  tl.fromTo(
    q('viewer'),
    { opacity: 0 },
    { opacity: 1, duration: 0.35, immediateRender: false },
    '<',
  )
  tl.to(q('view-session'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('view-setup'), { opacity: 1, duration: 0.2 }, '<')
  tl.fromTo(
    q('recent'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '<',
  )
  tl.set(q('recent-empty'), { opacity: 0 }, '<')
  move('download', { at: '+=0.3' })
  click('download')
  cursorOut('+=0.4')
  final()
  wait(1)

  tl.set(
    [q('view-session'), q('pill'), q('countdown'), q('viewer'), q('recent'), q('saved-banner')],
    { opacity: 0 },
    0,
  )
  tl.set(qa('timer'), { opacity: 0, text: '0:00' }, 0)
  tl.set(q('pill-timer'), { text: 'Starting' }, 0)
  tl.set(q('pause'), { display: 'none' }, 0)
}

function OptionRow({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-2 text-[9.5px] text-ink-soft">
      {label}
      {children}
    </div>
  )
}

